# test_group_by.py
import pytest

# Replace `your_module` with the module where group_by is defined.
from your_module import group_by


def test_group_by_happy_path_parity():
    items = [1, 2, 3, 4, 5]

    result = group_by(items, lambda x: x % 2)

    assert result == {
        1: [1, 3, 5],
        0: [2, 4],
    }


def test_group_by_strings_by_first_letter():
    items = ["apple", "apricot", "banana", "blueberry", "avocado"]

    result = group_by(items, lambda s: s[0])

    assert result == {
        "a": ["apple", "apricot", "avocado"],
        "b": ["banana", "blueberry"],
    }


def test_group_by_preserves_order_within_each_group():
    items = [1, 3, 2, 5, 4, 7]

    result = group_by(items, lambda x: "even" if x % 2 == 0 else "odd")

    assert result["odd"] == [1, 3, 5, 7]
    assert result["even"] == [2, 4]


def test_group_by_empty_list_returns_empty_dict():
    assert group_by([], lambda x: x) == {}


def test_group_by_single_item():
    assert group_by(["hello"], lambda s: len(s)) == {5: ["hello"]}


def test_group_by_all_items_same_key():
    items = [1, 2, 3]

    result = group_by(items, lambda _: "same")

    assert result == {"same": [1, 2, 3]}


def test_group_by_key_can_be_none():
    items = ["a", "bb", "ccc"]

    result = group_by(items, lambda _: None)

    assert result == {None: ["a", "bb", "ccc"]}


def test_group_by_items_can_be_unhashable_if_keys_are_hashable():
    items = [
        {"type": "fruit", "name": "apple"},
        {"type": "vegetable", "name": "carrot"},
        {"type": "fruit", "name": "banana"},
    ]

    result = group_by(items, lambda item: item["type"])

    assert result == {
        "fruit": [
            {"type": "fruit", "name": "apple"},
            {"type": "fruit", "name": "banana"},
        ],
        "vegetable": [
            {"type": "vegetable", "name": "carrot"},
        ],
    }


def test_group_by_calls_key_fn_once_per_item():
    items = [1, 2, 3]
    calls = []

    def key_fn(item):
        calls.append(item)
        return item % 2

    group_by(items, key_fn)

    assert calls == items


def test_group_by_raises_type_error_for_unhashable_key():
    items = [1, 2, 3]

    with pytest.raises(TypeError):
        group_by(items, lambda x: [x])


def test_group_by_propagates_exception_from_key_fn():
    class CustomError(Exception):
        pass

    def key_fn(item):
        if item == 2:
            raise CustomError("bad item")
        return item

    with pytest.raises(CustomError, match="bad item"):
        group_by([1, 2, 3], key_fn)


def test_group_by_raises_type_error_when_key_fn_is_not_callable():
    with pytest.raises(TypeError):
        group_by([1, 2, 3], None)


def test_group_by_raises_type_error_when_items_is_not_iterable():
    with pytest.raises(TypeError):
        group_by(None, lambda x: x)
